function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText ||
    source.text ||
    message.text ||
    message.caption ||
    payload.text ||
    ''
  ).trim();

  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseSheetTab(rawText) {
  const text = String(rawText || '').trim();

  // Hỗ trợ: tab Data, sheet tab Data, trang tính Data
  const match = text.match(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?([^:"'“”‘’]+?)["'“”‘’]?(?:\s*:|\s|$)/i);
  if (!match) return '';

  return cleanName(match[1]);
}

function parseAppendCommand(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'them dong vao sheet',
    'them dong sheet',
    'them dong vao bang tinh',
    'append row sheet',
    'append row',
    'add row sheet',
    'add row'
  ];

  let bodyOriginal = original;
  let bodyNormalized = normalized;

  for (const prefix of prefixes) {
    if (bodyNormalized.startsWith(prefix + ' ')) {
      bodyOriginal = original.slice(prefix.length + 1).trim();
      bodyNormalized = normalized.slice(prefix.length + 1).trim();
      break;
    }

    if (bodyNormalized === prefix) {
      return { sheetName: '', rowData: '' };
    }
  }

  const colonIndex = bodyOriginal.indexOf(':');
  if (colonIndex === -1) {
    return {
      sheetName: cleanName(bodyOriginal),
      rowData: ''
    };
  }

  let sheetName = bodyOriginal.slice(0, colonIndex).trim();
  const rowData = bodyOriginal.slice(colonIndex + 1).trim();

  const tab = parseSheetTab(sheetName);
  if (tab) {
    sheetName = sheetName
      .replace(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?[^:"'“”‘’]+?["'“”‘’]?$/i, '')
      .trim();
  }

  return {
    sheetName: cleanName(sheetName),
    rowData,
    sheetTab: tab
  };
}

function parseCsvLine(line) {
  const input = String(line || '');
  const values = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < input.length; i++) {
    const char = input[i];
    const next = input[i + 1];

    if (char === '"' && inQuotes && next === '"') {
      current += '"';
      i++;
      continue;
    }

    if (char === '"') {
      inQuotes = !inQuotes;
      continue;
    }

    if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
      continue;
    }

    current += char;
  }

  values.push(current.trim());
  return values.filter((value) => value !== '');
}

const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;

const parsed = parseAppendCommand(raw);

const spreadsheetId =
  source.spreadsheetId ||
  source.sheetId ||
  source.fileId ||
  source.targetId ||
  args.spreadsheetId ||
  args.sheetId ||
  args.fileId ||
  args.targetId ||
  ctx.payload.spreadsheetId ||
  ctx.payload.sheetId ||
  ctx.payload.fileId ||
  ctx.payload.targetId ||
  '';

const sheetTab =
  source.sheetTab ||
  args.sheetTab ||
  ctx.payload.sheetTab ||
  parsed.sheetTab ||
  '';

const sheetName = cleanName(
  source.sheetName ||
  source.targetName ||
  source.fileName ||
  source.title ||
  source.query ||
  args.sheetName ||
  args.targetName ||
  args.fileName ||
  args.title ||
  args.query ||
  ctx.payload.sheetName ||
  ctx.payload.targetName ||
  ctx.payload.fileName ||
  ctx.payload.title ||
  ctx.payload.query ||
  parsed.sheetName ||
  ''
);

const rowData = String(
  source.rowData ||
  source.content ||
  args.rowData ||
  args.content ||
  ctx.payload.rowData ||
  ctx.payload.content ||
  parsed.rowData ||
  ''
).trim();

const values = Array.isArray(source.values)
  ? source.values
  : Array.isArray(args.values)
    ? args.values
    : parseCsvLine(rowData);

const hasTarget = Boolean(spreadsheetId || sheetName);
const hasContent = values.length > 0;



// Stage 11 exact-id safety guard
const __stage11Pick = (...values) => {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'boolean') return value;
  }
  return '';
};
const __stage11Source = source || {};
const __stage11Args = args || __stage11Source.args || __stage11Source.payload?.args || {};
const __stage11Payload = typeof payload !== 'undefined' ? payload : (__stage11Source.payload || {});
const __stage11IdFields = ["spreadsheetId", "sheetId", "fileId", "targetId"];
const __stage11AlsoFields = ["values", "rowData"];
const __stage11HasId = Boolean(__stage11Pick(...__stage11IdFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11HasAlso = __stage11AlsoFields.length === 0 || Boolean(__stage11Pick(...__stage11AlsoFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11Allowed = __stage11HasId && __stage11HasAlso;
const __stage11Response = __stage11Allowed ? '' : "Mia chưa thêm dòng vào Google Sheet vì hành động này cần spreadsheetId cụ thể. Bạn hãy tìm sheet trước, chọn đúng bảng, rồi gửi lại kèm ID và dữ liệu dòng nhé.";

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalize(raw),

    spreadsheetId,
    sheetId: spreadsheetId,
    sheetName,
    query: sheetName,
    sheetTab,

    rowData,
    values,

    hasTarget: Boolean(hasTarget && __stage11Allowed),
    hasContent,
    response: __stage11Response ? __stage11Response : hasTarget && hasContent
      ? ''
      : '📊 <b>Thêm dòng vào Google Sheet</b>\n\nVí dụ:\n<code>thêm dòng vào sheet Chi tiêu: cafe,30000,ăn uống</code>\n<code>thêm dòng vào sheet Chi tiêu tab Data: cafe,30000,ăn uống</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      spreadsheetId: '',
      sheetId: '',
      found: false,
      response: 'Không tìm thấy Google Sheet phù hợp với: <b>' + escapeHtml(source.sheetName || source.targetName || source.query || '') + '</b>'
    }
  }];
}

const sheet = rows[0];

return [{
  json: {
    ...source,
    ...sheet,

    found: true,
    spreadsheetId: sheet.id || source.spreadsheetId || source.targetId || '',
    sheetId: sheet.id || source.sheetId || source.targetId || '',
    targetId: source.targetId || sheet.id || source.spreadsheetId || source.sheetId || '',
    sheetName: sheet.name || source.sheetName || source.targetName || source.query || '',
    targetName: source.targetName || sheet.name || source.sheetName || source.query || '',
    query: source.query || source.sheetName || source.targetName || '',
    webViewLink: sheet.webViewLink || source.webViewLink || '',
    mimeType: sheet.mimeType || source.mimeType || '',
    sheetTab: source.sheetTab || '',
    values: source.values || [],
    chatId: source.chatId || ''
  }
}];

function getJson(nodeName) {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
}

const source = {
  ...getJson('Prepare Action'),
  ...getJson('Resolve Search Result')
};
const result = $input.item.json || {};
const sheetId = source.spreadsheetId || source.sheetId || '';
const link = source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');
const updatedRange = result.updates?.updatedRange || result.updatedRange || '';
const shownTarget = source.sheetTab
  ? `${source.targetName || source.sheetName || 'Không rõ tên'} / tab ${source.sheetTab}`
  : (source.targetName || source.sheetName || 'Không rõ tên');
const addedColumns = Array.isArray(source.values) ? source.values.length : 0;

let text = `Đã thêm dòng vào Google Sheet: ${shownTarget}`;
if (sheetId) text += `\nID: ${sheetId}`;
if (updatedRange) text += `\nVùng cập nhật: ${updatedRange}`;
text += `\nSố cột đã thêm: ${addedColumns}`;
if (link) text += `\nMở bảng tính: ${link}`;

return [{ json: { chatId: source.chatId || result.chatId || '', text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
